function draw() {
  // === Variant 5: Symmetric Kaleidoscope Portal ===
  // Applying kaleidoscope coordinate distortion
  uM_rot = frameCount * 0.005;
  push();
  translate(width/2, height/2);
  rotate(uM_rot);
  scale(1.1);
  translate(-width/2, -height/2);

  background(10, 10, 15);
  randomSeed(240622);
  let r = int(random(3));
  let ratio;

  if (r === 0) {
    ratio = [1, 2];
  } else if (r === 1) {
    ratio = [3, 2];
  } else {
    ratio = [5, 1];
  }

  let offset = max(width, height) / 10; // 最小の辺に基づいてオフセットを設定

  drawRecursiveRect(
    offset,
    offset,
    width - 2 * offset,
    height - 2 * offset,
    ratio,
    margin,
    depth
  );

  pop();
}

function drawRecursiveRect(x, y, w, h, ratio, margin, depth) {
  if (depth === 0) {
    let n = noise((x / width) * 5, (y / height) * 5);
    let colors = shuffle(colorScheme[int(colorScheme.length * n)].colors);
    let isVertical = random() > 0.5;
    let g;
    if (isVertical) {
      g = drawingContext.createLinearGradient(-w / 2, 0, w / 2, 0);
    } else {
      g = drawingContext.createLinearGradient(0, -h / 2, 0, h / 2);
    }
    g.addColorStop(0, colors[0]);
    g.addColorStop(1, colors[1]);
    push();
    translate(x + w / 2, y + h / 2);
    scale(random() > 0.5 ? -1 : 1, random() > 0.5 ? -1 : 1);
    let t =
      dist(x + w / 2, y + h / 2, width / 2, height / 2) /
      sqrt(width * width + height * height) /
      2;
    let v = Easing.easeInOutQuint(abs(((t + frameCount / 150) % 1)));
    noStroke();
    fill(255, 0);
    // scale(v);
    rectMode(CENTER);
    rect(0, 0, w - 2, h - 2);
    // scale(1/v);
    drawingContext.clip();
    stroke(0, 255);
    drawingContext.strokeStyle = g;
    strokeCap(ROUND);
    let minSW = min(w,h);
    strokeWeight(minSW/20)
    if (w>h) {
      line(-w,0,w,0);
      strokeWeight(sw = minSW * random(0.5,1));
      drawingContext.setLineDash([.1,minSW*1.1]);
      drawingContext.lineDashOffset = minSW * 1.1 * v + minSW/2;
      line(-w, 0, w, 0);
    } else {
      line(0,-h,0,h);
      strokeWeight(minSW/2);
      drawingContext.setLineDash([.1,minSW*1.1]);
      drawingContext.lineDashOffset = minSW * 1.1 * v;
      line(0, -h, 0, h);
    }
    // rectMode(CENTER);
    // noStroke();
    // rect(0, 0, w, h);
    pop();
    return;
  }

  let total = ratio[0] + ratio[1];
  let newRatio;

  if (random() < 0.5) {
    let firstRectWidth = w * (ratio[0] / total);
    let secondRectWidth = w * (ratio[1] / total);

    newRatio = getRandomRatio(min(w, h));
    drawRecursiveRect(
      x,
      y,
      firstRectWidth - margin,
      h,
      newRatio,
      margin,
      depth - 1
    );
    newRatio = getRandomRatio(min(w, h));
    drawRecursiveRect(
      x + firstRectWidth + margin,
      y,
      secondRectWidth - margin,
      h,
      newRatio,
      margin,
      depth - 1
    );
  } else {
    // 横で分割
    let firstRectHeight = h * (ratio[0] / total);
    let secondRectHeight = h * (ratio[1] / total);

    newRatio = getRandomRatio(min(w, h));
    drawRecursiveRect(
      x,
      y,
      w,
      firstRectHeight - margin,
      newRatio,
      margin,
      depth - 1
    );
    newRatio = getRandomRatio(min(w, h));
    drawRecursiveRect(
      x,
      y + firstRectHeight + margin,
      w,
      secondRectHeight - margin,
      newRatio,
      margin,
      depth - 1
    );
  }
}

function getRandomRatio(size) {
  let r = int(random(3));
  if (size < max(width, height) / 10) {
    return [1, 1];
  }
  if (r === 0) {
    return [1, 2];
  } else if (r === 1) {
    return [3, 2];
  } else {
    return [5, 1];
  }
}

